-- ───────── 사용자 제재 ─────────
CREATE TABLE "sanction" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "report_id" bigint,
  "imposed_by" bigint,
  "reason" varchar NOT NULL,
  "starts_at" timestamp NOT NULL,
  "until" timestamp,
  "permanent" boolean NOT NULL DEFAULT false,
  "revoked_at" timestamp,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  "deleted_at" timestamp
);

COMMENT ON TABLE "sanction" IS '사용자 제재. 허위 제보 1회 7일 · 2회 14일 · 3회 이상 영구';
COMMENT ON COLUMN "sanction"."report_id" IS '원인 제보 (없을 수 있음)';
COMMENT ON COLUMN "sanction"."imposed_by" IS '부과한 관리자·시청 사용자';
COMMENT ON COLUMN "sanction"."reason" IS '제재 사유 (사용자에게 보임)';
COMMENT ON COLUMN "sanction"."starts_at" IS '시작 시각. 제재 중에 추가로 부과되면 기존 종료 시각부터 시작';
COMMENT ON COLUMN "sanction"."until" IS '종료 시각. 영구면 null';
COMMENT ON COLUMN "sanction"."permanent" IS '영구 제재 여부';
COMMENT ON COLUMN "sanction"."revoked_at" IS '관리자 해제 시각. 해제된 제재는 누적 횟수에서 제외';

ALTER TABLE "sanction" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "sanction" ADD FOREIGN KEY ("report_id") REFERENCES "report" ("id");
ALTER TABLE "sanction" ADD FOREIGN KEY ("imposed_by") REFERENCES "users" ("id");
CREATE INDEX idx_sanction_user ON "sanction" ("user_id", "starts_at");
